using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.Mvc.ModelBinding.Validation;

namespace NexusCommunication.Models;

/// <summary>
/// A purchase list / order placed with a manufacturing vendor (Admin only).
/// Number, status, totals and dates are maintained by the server and cannot be over-posted.
/// </summary>
public class PurchaseOrder
{
    public int Id { get; set; }

    /// <summary>Generated by the server (PO000001 ...).</summary>
    [BindNever, ValidateNever]
    [MaxLength(20)] public string PoNumber { get; set; } = "";

    [Range(1, int.MaxValue, ErrorMessage = "Please select a vendor.")]
    public int VendorId { get; set; }
    public Vendor? Vendor { get; set; }

    [BindNever]
    public DateTime OrderDate { get; set; } = DateTime.UtcNow;

    [BindNever]
    public PurchaseOrderStatus Status { get; set; } = PurchaseOrderStatus.Ordered;

    /// <summary>Total cost of all items (server calculated).</summary>
    [BindNever]
    public decimal TotalAmount { get; set; }

    /// <summary>Total paid to the vendor so far (server maintained).</summary>
    [BindNever]
    public decimal AmountPaid { get; set; }

    [BindNever]
    public DateTime? ReceivedOn { get; set; }

    [BindNever]
    public int CreatedByEmployeeId { get; set; }

    public List<PurchaseOrderItem> Items { get; set; } = new();
    public List<VendorPayment> Payments { get; set; } = new();
}
